import type Database from 'better-sqlite3';
import { connectionStatus } from '../api-access';
import type { FilingProvider, FilingProviderId, FilingResult } from './types';

// Form code -> the system it is filed to. FORM_PROVIDER is the single mapping; SAM / 1-SD are not generated by the program yet.
export const FORM_PROVIDER: Record<string, FilingProviderId> = {
  FR0600: 'VMI_EDS', FR0564: 'VMI_EDS', GPM313: 'VMI_EDS', GPM312: 'VMI_EDS', PLN204: 'VMI_EDS', ISAF: 'VMI_EDS',
  SAM: 'SODRA_EDAS', '1-SD': 'SODRA_EDAS',
  FINANCIAL_STATEMENTS: 'RC',
};

const notImplemented = (message: string): FilingResult => ({ result: 'NOT_IMPLEMENTED', message, ref: null });

function provider(id: FilingProviderId, label: string, manualUrl: string, message: string): FilingProvider {
  return {
    id, label, manualUrl,
    supports: formCode => FORM_PROVIDER[formCode] === id,
    status: (db: Database.Database, companyId: number) => connectionStatus(db, companyId, id),
    submit: async () => notImplemented(message),
    checkStatus: async () => notImplemented(message),
  };
}

export const PROVIDERS: Record<FilingProviderId, FilingProvider> = {
  VMI_EDS: provider('VMI_EDS', 'VMI EDS', 'https://deklaravimas.vmi.lt',
    'Duomenų siuntimas į VMI dar neprijungtas: VMI EDS žiniatinklio paslaugos specifikacija dar negauta. Atsisiųskite failą ir pateikite EDS rankiniu būdu.'),
  SODRA_EDAS: provider('SODRA_EDAS', 'Sodra EDAS', 'https://draudejai.sodra.lt',
    'Duomenų siuntimas į Sodrą dar neprijungtas: EDAS duomenų perdavimo sąsaja dar neįdiegta. Atsisiųskite failą ir pateikite EDAS rankiniu būdu.'),
  RC: provider('RC', 'Registrų centras', 'https://www.registrucentras.lt',
    'Duomenų siuntimas į Registrų centrą neįmanomas: finansinių ataskaitų teikimo sąsajos nėra. Atsisiųskite failą ir pateikite Registrų centro e. paslaugose rankiniu būdu.'),
};
